def group_by_digit_count(nums):
    d = {}
    for x in nums:
        dc = len(str(abs(x)))
        d.setdefault(dc, []).append(x)
    return {k: sorted(v) for k, v in d.items()}

def anagram_groups(words):
    d = {}
    for w in words:
        key = "".join(sorted(w))
        d.setdefault(key, []).append(w)
    return {k: sorted(v) for k, v in d.items()}

def words_appearing_once(text):
    counts = {}
    for w in text.split():
        counts[w] = counts.get(w, 0) + 1
    return sorted(w for w, c in counts.items() if c == 1)

def is_palindrome_identifier(s):
    if not s or not s.isalnum():
        return False
    lowered = s.lower()
    return lowered == lowered[::-1]

def are_all_rotations_equal(lst):
