        return True
    return all(x == lst[0] for x in lst)

def group_by_length_parity(strings):
    res = {"even_length": [], "odd_length": []}
    for s in strings:
        if len(s) % 2 == 0:
            res["even_length"].append(s)
        else:
            res["odd_length"].append(s)
    res["even_length"] = sorted(res["even_length"])
    res["odd_length"] = sorted(res["odd_length"])
    return res

def is_valid_simple_url(s):
    if ' ' in s:
        return False
    rest = None
    for prefix in ('http://', 'https://'):
        if s.startswith(prefix):
            rest = s[len(prefix):]
            break
    if rest is None or not rest:
        return False
    slash_idx = rest.find('/')
    domain = rest if slash_idx == -1 else rest[:slash_idx]
    if not domain:
        return False
    labels = domain.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not label or label.startswith('-') or label.endswith('-'):
            return False
        if not all(c.isalnum() or c == '-' for c in label):
            return False
    tld = labels[-1]
    return tld.isalpha() and len(tld) >= 2

def wrap_indent_block(text, width, indent):
    words = text.split()
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    prefix = ' ' * indent
    return '\n'.join(prefix + line for line in lines)

