def most_frequent_char(s):
    if not s:
        return ""
    freq = {}
    order = []
    for ch in s:
        if ch not in freq:
            freq[ch] = 0
            order.append(ch)
        freq[ch] += 1
    best = order[0]
    for ch in order[1:]:
        if freq[ch] > freq[best]:
            best = ch
    return best

def count_weekend_days_breakdown(year, month):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def wd(y, m, d):
        if m < 3:
            m += 12
            y -= 1
        K = y % 100
        J = y // 100
        h = (d + (13 * (m + 1)) // 5 + K + K // 4 + J // 4 + 5 * J) % 7
        return (h + 5) % 7
    dim = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
    sat = sun = 0
    for d in range(1, dim + 1):
        w = wd(year, month, d)
        if w == 5:
            sat += 1
        elif w == 6:
            sun += 1
    return (sat, sun)

