def rank_by_value_dense(d):
    distinct_sorted = sorted(set(d.values()), reverse=True)
    rank_of = {v: i + 1 for i, v in enumerate(distinct_sorted)}
    return {k: rank_of[v] for k, v in d.items()}

def find_min_sum_subarray_of_size_k(lst, k):
    best = cur = sum(lst[:k])
    for i in range(k, len(lst)):
        cur += lst[i] - lst[i - k]
        best = min(best, cur)
    return best

def truncate_words_ellipsis(s, maxwords):
    words = s.split()
    if len(words) <= maxwords:
        return ' '.join(words)
    return ' '.join(words[:maxwords]) + '...'

def count_armstrong_in_range(a, b):
    count = 0
    for x in range(a, b + 1):
        s = str(x)
        k = len(s)
        if sum(int(d) ** k for d in s) == x:
            count += 1
    return count

def longest_run_length(lst):
    if not lst:
        return 0
    best = cur = 1
    for i in range(1, len(lst)):
        if lst[i] == lst[i-1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def total_break_minutes(schedule):
    if len(schedule) < 2:
        return 0
    total = 0
    for i in range(1, len(schedule)):
        total += schedule[i][0] - schedule[i-1][1]
    return total

def camel_case_acronym(s):
    if not s:
        return ""
    result = [s[0].upper()]
    for c in s[1:]:
        if c.isupper():
            result.append(c)
    return "".join(result)

