def interleave_two_rankings(list1, list2):
    result = []
    seen = set()
    i = j = 0
    turn = 0
    while i < len(list1) or j < len(list2):
        if turn == 0:
            if i < len(list1):
                if list1[i] not in seen:
                    result.append(list1[i])
                    seen.add(list1[i])
                i += 1
            turn = 1
        else:
            if j < len(list2):
                if list2[j] not in seen:
                    result.append(list2[j])
                    seen.add(list2[j])
                j += 1
            turn = 0
        if i >= len(list1) and j >= len(list2):
            break
    return result

def find_repeated_substrings_of_length(s, k):
    if k <= 0 or k > len(s):
        return []
    from collections import Counter
    subs = [s[i:i + k] for i in range(len(s) - k + 1)]
    counts = Counter(subs)
    seen = set()
    result = []
    for sub in subs:
        if counts[sub] > 1 and sub not in seen:
            result.append(sub)
            seen.add(sub)
    return result

def vowel_consonant_count(s):
    vowels = set("aeiouAEIOU")
    v = 0
    c = 0
    for ch in s:
        if ch.isalpha():
            if ch in vowels:
                v += 1
            else:
                c += 1
    return {"vowels": v, "consonants": c}

def matches_wildcard(s, pattern):
    m, n = len(s), len(pattern)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for j in range(1, n + 1):
        if pattern[j-1] == '*':
            dp[0][j] = dp[0][j-1]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[j-1] == '*':
                dp[i][j] = dp[i-1][j] or dp[i][j-1]
            elif pattern[j-1] == '?' or s[i-1] == pattern[j-1]:
                dp[i][j] = dp[i-1][j-1]
    return dp[m][n]

def is_not_common_password(s, common_list):
    if len(s) < 8:
        return False
    return s.lower() not in {x.lower() for x in common_list}

def sum_of_divisors_squared(n):
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i * i
            j = n // i
            if j != i:
                total += j * j
        i += 1
    return total

def sort_by_frequency_desc_then_first_occurrence(nums):
    from collections import Counter
    c = Counter(nums)
    first_idx = {}
    for i, x in enumerate(nums):
        if x not in first_idx:
            first_idx[x] = i
    return sorted(c.keys(), key=lambda v: (-c[v], first_idx[v]))
